function loadState(){try{const raw=localStorage.getItem(KEY);if(!raw)return freshState();const parsed=JSON.parse(raw);if(!parsed||typeof parsed!=="object"||!parsed.profile||!Array.isArray(parsed.quests))return freshState();const base=freshState();const loaded={...base,...parsed,version:7,profile:{...base.profile,...parsed.profile},settings:{...base.settings,...(parsed.settings||{})},focusSession:parsed.focusSession||null,focusLogs:parsed.focusLogs||[],restDays:parsed.restDays||[],lastBackupReminder:parsed.lastBackupReminder||null,notifiedKeys:parsed.notifiedKeys||[],mainGoals:parsed.mainGoals||[],failureReasons:parsed.failureReasons||[],minimumDays:parsed.minimumDays||[],minimumChecklist:parsed.minimumChecklist||{},skillsUnlocked:parsed.skillsUnlocked||[],skillSteps:parsed.skillSteps||{},achievementsUnlocked:parsed.achievementsUnlocked||[],weeklyBoss:parsed.weeklyBoss||null,archive:parsed.archive||[],stats:{...base.stats,...parsed.stats},dungeons:parsed.dungeons||{},transactions:parsed.transactions||[],history:parsed.history||[],inventory:parsed.inventory||[],penalties:parsed.penalties||[],usedItems:parsed.usedItems||[],shadows:parsed.shadows||[],titles:parsed.titles||["Awakened"]};if(!parsed.dungeonSystem){const done=loaded.quests.filter(q=>q.status==="done").length;const passed=Array.from({length:Math.floor(done/10)},(_,i)=>(i+1)*10);loaded.dungeonSystem={triggeredMilestones:passed,pendingMilestones:[],current:null,history:[],shadows:[]};}else loaded.dungeonSystem={triggeredMilestones:[],pendingMilestones:[],current:null,history:[],shadows:[],...parsed.dungeonSystem};return loaded;}catch(e){return freshState();}}
