function dateText(iso){if(!iso)return "بدون موعد";const d=new Date(iso);if(Number.isNaN(d.getTime()))return "موعد غير صالح";return d.toLocaleString("ar-EG",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"});}
