function toast(msg){const el=$("toast");el.textContent=msg;el.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("show"),3200);}
function showNotice(msg){const el=$("notice");if(!el)return;if(!msg){el.textContent="";el.classList.add("hidden");return;}el.textContent=msg;el.classList.remove("hidden");}
