function xpForLevel(level){return 1000+Math.max(0,level-1)*250;}
function totalXPForLevel(level){let total=0;for(let i=1;i<level;i++)total+=xpForLevel(i);return total;}
function updateLevel(){let level=1;while(state.xp>=totalXPForLevel(level+1)&&level<999){level++;}state.level=level;}
function levelProgress(){updateLevel();const start=totalXPForLevel(state.level),needed=xpForLevel(state.level);return {earned:Math.max(0,state.xp-start),needed,percent:Math.max(0,Math.min(100,(state.xp-start)/needed*100))};}
