function makeQuestFromForm(){const id=$("questId").value;const existing=state.quests.find(q=>q.id===id);if(existing&&state.settings.strictMode&&Date.now()-new Date(existing.createdAt).getTime()>600000){toast("Strict Mode: انتهت مهلة التعديل بعد 10 دقائق من إنشاء المهمة.");closeDialog("questDialog");return;}const name=$("questName").value.trim(),xp=Math.max(1,Math.min(100,Number($("questXP").value)||1)),dc=Math.max(1,Math.min(25,Number($("questDC").value)||1)),deadline=$("questDeadline").value?new Date($("questDeadline").value).toISOString():null;const old=state.quests.find(q=>q.id===id);const q={id:id||uid(),name,type:$("questType").value,stat:$("questStat").value,difficulty:$("questDifficulty").value,xpReward:xp,dcReward:dc,deadline,description:$("questDescription").value.trim(),focusMinutes:Number($("questFocusMinutes").value)||0,focusSeconds:old?.focusSeconds||0,focusSessions:old?.focusSessions||0,status:old?.status||"active",createdAt:old?.createdAt||dateNow(),completedAt:old?.completedAt||null,penaltyCreated:old?.penaltyCreated||false,dcShielded:old?.dcShielded||false,boostXP:old?.boostXP||false,boostDC:old?.boostDC||false};if(old){state.quests=state.quests.map(x=>x.id===id?q:x);logActivity("تم تعديل المهمة: "+name);}else{state.quests.unshift(q);logActivity("مهمة جديدة: "+name);}$("questDialog").close();save();render();toast(old?"تم تحديث المهمة":"تمت إضافة المهمة");}
function activeItem(id){return state.inventory.find(i=>i.id===id&&i.qty>0);}
function completeQuest(id){const q=state.quests.find(q=>q.id===id);if(!q||q.status!=="active")return;if(q.focusMinutes>0&&(q.focusSeconds||0)<q.focusMinutes*60){toast(`المهمة مرتبطة بجلسة ${q.focusMinutes} دقيقة. أكمل جلسة التركيز أولًا.`);return;}if(pendingPenalties().length){toast("عندك عقوبة مستحقة. نفّذها أولًا لتحصيل مكافأة المهمة.");go("penalties");return;}const xp=q.xpReward,dc=q.dcReward;if(!Number.isFinite(xp)||!Number.isFinite(dc))return;let earnedXP=xp,earnedDC=dc;if(q.boostXP){earnedXP=Math.min(100,Math.ceil(xp*1.1));q.boostXP=false;}if(q.boostDC){earnedDC=Math.min(25,Math.ceil(dc*1.2));q.boostDC=false;}state.xp+=earnedXP;state.coins+=earnedDC;state.stats[q.stat]=Math.min(999,(state.stats[q.stat]||1)+Math.max(1,Math.floor(earnedXP/20)));q.status="done";q.completedAt=dateNow();if(q.goalId){const g=state.mainGoals.find(x=>x.id===q.goalId);if(g){g.completedTasks=(g.completedTasks||0)+1;const m=(g.milestones||[]).find(x=>x.id===q.goalMilestoneId)||g.milestones?.find(x=>!x.done);if(m)m.done=true;g.updatedAt=dateNow();}}state.archive=state.archive||[];state.archive.unshift({type:"quest_done",text:"أكملت المهمة: "+q.name,at:dateNow()});state.archive=state.archive.slice(0,300);updateLevel();let today=new Date().toDateString();if(state.lastCompleteDate!==today){state.streak=state.lastCompleteDate&&new Date(state.lastCompleteDate).toDateString()===new Date(Date.now()-86400000).toDateString()?state.streak+1:1;state.lastCompleteDate=dateNow();}transaction("إكمال: "+q.name,earnedDC,"in");logActivity("أكملت المهمة: "+q.name,"success");checkShadows();queueDungeonMilestones();if(state.streak>=7&&!state.titles.includes("Consistent Hunter"))state.titles.push("Consistent Hunter");save();render();toast(`تم إكمال المهمة! +${earnedXP} XP و +${earnedDC} DC`);setTimeout(promptDungeonIfNeeded,180);}
function consumeInventory(id){const item=activeItem(id);if(item){item.qty--;if(item.qty<=0)state.inventory=state.inventory.filter(i=>i.qty>0);}}
function failQuest(id){const q=state.quests.find(q=>q.id===id);if(!q||q.status!=="active")return;confirmAction("تسجيل فشل المهمة","سيتم تسجيل الفشل وإنشاء عقوبة بناءة. هل تريد المتابعة؟",()=>{const reason=window.prompt("إيه السبب الأساسي للتعثر؟ (اختياري: نوم، ضغط، تقدير وقت، تشتت، صعوبة، غيره)","");q.status="failed";q.failedAt=dateNow();q.failureReason=(reason||"لم يُسجل").trim();state.failureReasons.unshift({id:uid(),questId:q.id,questName:q.name,reason:q.failureReason,at:dateNow()});state.failureReasons=state.failureReasons.slice(0,200);const shieldProtected=!!q.dcShielded;if(shieldProtected){q.dcShielded=false;logActivity("درع الانضباط منع خصم العملات عن: "+q.name,"success");}else{const loss=Math.min(5,state.coins);state.coins-=loss;if(loss>0)transaction("خصم بسبب فشل: "+q.name,-loss,"out");}if(!q.penaltyCreated){state.penalties.unshift({id:uid(),name:"مراجعة سبب الفشل: "+q.name,reason:"انتهى موعد المهمة أو تم تسجيل فشلها",type:"missed",done:false,createdAt:dateNow(),questId:q.id});q.penaltyCreated=true;}logActivity("فشل المهمة: "+q.name,"danger");state.archive=state.archive||[];state.archive.unshift({type:"quest_failed",text:"تعثر: "+q.name+" — "+q.failureReason,at:dateNow()});state.archive=state.archive.slice(0,300);save();render();toast(shieldProtected?"تم تسجيل الفشل وإنشاء العقوبة دون خصم العملات.":"تم تسجيل الفشل وخصم حتى 5 DC وإنشاء عقوبة.");});}
function deleteQuest(id){const target=state.quests.find(q=>q.id===id);if(state.settings.strictMode&&target&&Date.now()-new Date(target.createdAt).getTime()>10*60*1000){toast("Strict Mode: لا يمكن حذف المهمة بعد مرور 10 دقائق.");return;}confirmAction("حذف المهمة","سيتم حذف المهمة من القائمة. لا يمكن التراجع عن الحذف إلا باستعادة نسخة احتياطية.",()=>{const q=state.quests.find(q=>q.id===id);state.quests=state.quests.filter(q=>q.id!==id);logActivity("حذف مهمة: "+(q?.name||"غير معروفة"));save();render();toast("تم حذف المهمة");});}
function checkDeadlines(){let changed=false;const now=Date.now();state.quests.forEach(q=>{if(q.status==="active"&&q.deadline&&new Date(q.deadline).getTime()<now&&!q.penaltyCreated){q.status="failed";q.failedAt=dateNow();q.penaltyCreated=true;state.penalties.unshift({id:uid(),name:"مراجعة سبب الفشل: "+q.name,reason:"انتهى الموعد النهائي تلقائيًا",type:"missed",done:false,createdAt:dateNow(),questId:q.id});logActivity("انتهى موعد المهمة: "+q.name,"danger");changed=true;}});if(changed){save();showNotice("انتهى موعد مهمة واحدة أو أكثر. تمت إضافة العقوبات إلى قائمة العقوبات المستحقة.");}}
function addPenalty(){const name=$("penaltyName").value.trim();if(!name)return;state.penalties.unshift({id:uid(),name,reason:$("penaltyReason").value.trim(),type:$("penaltyType").value,done:false,createdAt:dateNow()});logActivity("إضافة عقوبة: "+name,"danger");$("penaltyDialog").close();save();render();toast("تمت إضافة العقوبة");}
function completePenalty(id){const p=state.penalties.find(p=>p.id===id);if(!p||p.done)return;confirmAction("تأكيد تنفيذ العقوبة","هل نفذت هذه المهمة فعلًا؟ سجّلها مكتملة فقط بعد تنفيذها.",()=>{p.done=true;p.completedAt=dateNow();logActivity("تنفيذ العقوبة: "+p.name,"success");save();render();toast("تم تسجيل تنفيذ العقوبة. يمكنك الآن تحصيل مكافآت المهام.");});}
function buyItem(id){if(!shopUnlocked()){toast("المتجر يُفتح عند رتبة A فقط.");return;}const item=SHOP.find(x=>x.id===id);if(!item)return;if(state.coins<item.price){toast("رصيدك غير كافٍ لشراء هذا العنصر.");return;}if(pendingPenalties().length){toast("نفّذ العقوبات المستحقة قبل الشراء.");return;}state.coins-=item.price;const existing=state.inventory.find(i=>i.id===id);if(existing)existing.qty++;else state.inventory.push({id,qty:1,boughtAt:dateNow()});transaction("شراء: "+item.ar,-item.price,"out");logActivity("شراء عنصر: "+item.ar);save();render();toast("تم شراء "+item.ar+" وإضافته للمخزون");}
function useItem(id){if(!shopUnlocked())return;const item=activeItem(id);if(!item)return;if(id==="time"){const active=state.quests.filter(q=>q.status==="active"&&q.deadline&&new Date(q.deadline).getTime()>Date.now());if(!active.length){toast("لا توجد مهمة نشطة لها موعد مستقبلي. العنصر لم يُستهلك.");return;}const choice=active[0];choice.deadline=new Date(new Date(choice.deadline).getTime()+2*60*60*1000).toISOString();consumeInventory(id);logActivity("تمديد موعد المهمة ساعتين: "+choice.name);toast("تم تمديد أقرب موعد ساعتين: "+choice.name);}else if(id==="leisure"){consumeInventory(id);logActivity("تفعيل تصريح الترفيه: ساعتان مخطط لهما");state.titles.includes("Balanced Hunter")||state.titles.push("Balanced Hunter");toast("تم تسجيل ساعتين ترفيه مخطط لهما. استمتع بدون تأنيب.");}else if(id==="shield"){const q=state.quests.find(q=>q.status==="active"&&!q.dcShielded);if(!q){toast("لا توجد مهمة نشطة لتعيين الدرع لها.");return;}q.dcShielded=true;consumeInventory(id);logActivity("تفعيل درع الانضباط للمهمة: "+q.name);toast("الدرع فعّال للمهمة: "+q.name);}else if(id==="sword"){const q=state.quests.find(q=>q.status==="active"&&!q.boostXP);if(!q){toast("لا توجد مهمة نشطة لتفعيل السيف عليها.");return;}q.boostXP=true;consumeInventory(id);logActivity("تفعيل سيف التركيز للمهمة: "+q.name);toast("تم تفعيل زيادة XP للمهمة: "+q.name);}else if(id==="spear"){const q=state.quests.find(q=>q.status==="active"&&!q.boostDC);if(!q){toast("لا توجد مهمة نشطة لتفعيل الرمح عليها.");return;}q.boostDC=true;consumeInventory(id);logActivity("تفعيل رمح الصياد للمهمة: "+q.name);toast("تم تفعيل زيادة DC للمهمة: "+q.name);}save();render();}
function checkShadows(){const total=state.quests.filter(q=>q.status==="done").length;SHADOWS.forEach(s=>{if(total>=s.at&&!state.shadows.includes(s.id)){state.shadows.push(s.id);logActivity("استخراج ظل جديد: "+s.name,"success");if(!state.titles.includes(s.name))state.titles.push(s.name);}});}
function queueDungeonMilestones(){const done=state.quests.filter(q=>q.status==="done").length,ds=state.dungeonSystem;for(let milestone=10;milestone<=done;milestone+=10){if(!ds.triggeredMilestones.includes(milestone)){ds.triggeredMilestones.push(milestone);ds.pendingMilestones.push(milestone);logActivity(`ظهرت زنزانة جديدة بعد إكمال ${milestone} مهمة` ,"success");}}}
function nextDungeonMilestone(){const done=state.quests.filter(q=>q.status==="done").length;return (Math.floor(done/10)+1)*10;}
function dungeonRank(){return rank().name;}
function promptDungeonIfNeeded(){const ds=state.dungeonSystem;if(!ds||ds.current||!ds.pendingMilestones.length||!$("dungeonDialog")||$("dungeonDialog").open)return;const milestone=ds.pendingMilestones[0],r=dungeonRank(),cfg=DUNGEON_CHALLENGES[r]||DUNGEON_CHALLENGES.E;$("dungeonMilestone").textContent=`بعد ${milestone} مهمة مكتملة`;$("dungeonRank").textContent=`RANK ${r}`;$("dungeonDuration").textContent=`${cfg.days} يوم`;$("dungeonPreview").innerHTML=cfg.steps.map((x,i)=>`<li>${esc(x)}</li>`).join("");$("dungeonBossName").value="";openDialog("dungeonDialog");}
function startDungeon(){const ds=state.dungeonSystem;if(ds.current||!ds.pendingMilestones.length)return;const boss=$("dungeonBossName").value.trim();if(!boss){toast("اكتب اسم العادة السيئة التي تريد مواجهتها أولًا.");$("dungeonBossName").focus();return;}const milestone=ds.pendingMilestones.shift(),r=dungeonRank(),cfg=DUNGEON_CHALLENGES[r]||DUNGEON_CHALLENGES.E;ds.current={id:uid(),milestone,rank:r,boss,startedAt:dateNow(),deadlineAt:new Date(Date.now()+cfg.days*86400000).toISOString(),durationDays:cfg.days,rewardXP:cfg.xp,rewardDC:cfg.dc,steps:cfg.steps.map((text,i)=>({id:`step-${i+1}`,text,done:false})),status:"active"};logActivity(`بدأت زنزانة رتبة ${r}: مواجهة عادة ${boss}`);save();closeDialog("dungeonDialog");render();go("dungeons");toast(`تم فتح الزنزانة! واجه الزعيم: ${boss}`);}
function toggleDungeonStep(id){const d=state.dungeonSystem.current;if(!d||d.status!=="active")return;const step=d.steps.find(x=>x.id===id);if(!step)return;step.done=!step.done;save();renderDungeons();}
function defeatDungeon(){const ds=state.dungeonSystem,d=ds.current;if(!d||d.status!=="active")return;if(d.steps.some(s=>!s.done)){toast("أكمل كل أهداف الزنزانة قبل هزيمة الزعيم.");return;}if(pendingPenalties().length){toast("نفّذ العقوبات المستحقة قبل تحصيل مكافأة الزنزانة.");go("penalties");return;}d.status="defeated";d.defeatedAt=dateNow();ds.history.unshift(d);ds.current=null;state.xp+=d.rewardXP;state.coins+=d.rewardDC;state.stats.discipline=Math.min(999,(state.stats.discipline||1)+2);updateLevel();transaction(`مكافأة زنزانة: ${d.boss}`,d.rewardDC,"in");logActivity(`هزمت زعيم الزنزانة: ${d.boss}` ,"success");save();render();toast(`الزعيم سقط! +${d.rewardXP} XP و +${d.rewardDC} DC — تقدر تعمل له ARISE من الزنزانات أو جيش الظلال.`);setTimeout(promptDungeonIfNeeded,180);}
function ariseBoss(id){const ds=state.dungeonSystem,d=ds.history.find(x=>x.id===id);if(!d||d.status!=="defeated"||d.arisen)return;const count=state.shadows.length+(ds.shadows||[]).length;if(count>=shadowLimit()){toast("جيش الظلال وصل الحد الأقصى لرتبتك. ارفع رتبتك لضم ظلال جديدة.");return;}d.arisen=true;d.arisenAt=dateNow();ds.shadows.unshift({id:`boss-${d.id}`,name:d.boss,rank:d.rank,sourceDungeon:d.id,arisenAt:d.arisenAt,desc:`زعيم زنزانة رتبة ${d.rank} — عادة واجهتها وتعلّمت كيف تتحكم فيها بدل أن تتحكم فيك.`});if(!state.titles.includes("Shadow Tamer"))state.titles.push("Shadow Tamer");logActivity(`ARISE: انضم ظل العادة «${d.boss}» إلى جيش الظلال`,"success");save();render();toast(`ARISE! ${d.boss} أصبح ظلًا في جيشك.`);}
function retryDungeon(id){const ds=state.dungeonSystem,d=ds.history.find(x=>x.id===id);if(!d||d.status!=="expired"||ds.current)return;const cfg=DUNGEON_CHALLENGES[d.rank]||DUNGEON_CHALLENGES.E;ds.current={...d,id:uid(),startedAt:dateNow(),deadlineAt:new Date(Date.now()+cfg.days*86400000).toISOString(),steps:d.steps.map(x=>({...x,done:false})),status:"active"};logActivity(`إعادة محاولة زنزانة العادة: ${d.boss}`);save();render();go("dungeons");}
function checkDungeonDeadline(){const d=state.dungeonSystem.current;if(!d||d.status!=="active"||Date.now()<=new Date(d.deadlineAt).getTime())return;d.status="expired";d.expiredAt=dateNow();state.dungeonSystem.history.unshift(d);state.dungeonSystem.current=null;logActivity(`انتهى وقت زنزانة العادة: ${d.boss}`,"danger");save();render();toast("انتهى وقت الزنزانة. تقدر تعيد المحاولة من صفحة الزنزانات.");setTimeout(promptDungeonIfNeeded,180);}
function exportBackup(){state.lastBackupReminder=dateNow();save();const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="solo-leveling-backup-v5-"+new Date().toISOString().slice(0,10)+".json";document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast("تم تجهيز ملف النسخة الاحتياطية");}
function importBackup(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!data||!Array.isArray(data.quests)||!data.profile||typeof data.xp!=="number")throw new Error("invalid");confirmAction("استعادة النسخة الاحتياطية","سيتم استبدال التقدم الحالي بمحتوى الملف. تأكد من تصدير نسخة حالية أولًا.",()=>{state={...freshState(),...data,version:7,settings:{...freshState().settings,...(data.settings||{})},focusLogs:data.focusLogs||[],restDays:data.restDays||[],notifiedKeys:data.notifiedKeys||[]};if(!data.dungeonSystem){const done=state.quests.filter(q=>q.status==="done").length;state.dungeonSystem={triggeredMilestones:Array.from({length:Math.floor(done/10)},(_,i)=>(i+1)*10),pendingMilestones:[],current:null,history:[],shadows:[]};}else state.dungeonSystem={...freshState().dungeonSystem,...data.dungeonSystem};save();render();toast("تمت استعادة النسخة الاحتياطية");});}catch(e){toast("ملف النسخة الاحتياطية غير صالح.");}};reader.readAsText(file);}
function resetSystem(){confirmAction("إعادة ضبط النظام","سيتم حذف كل المهام والعملات والإحصائيات المحفوظة محليًا. صدّر نسخة احتياطية أولًا إن أردت الاحتفاظ بها.",()=>{state=freshState();try{localStorage.removeItem(KEY);}catch(e){}save();showNotice("");render();go("dashboard");toast("تمت إعادة ضبط النظام");});}
function renderDashboard(){
 const active=state.quests.filter(q=>q.status==="active").sort((a,b)=>new Date(a.deadline||"9999-12-31")-new Date(b.deadline||"9999-12-31")).slice(0,5);
 const dashboardQuests=$("dashboardQuests");
 if(dashboardQuests) dashboardQuests.innerHTML=active.length?active.map(q=>`<div class="stack-item"><span class="stat-icon">${q.type==="main"?"✦":"◈"}</span><div class="stack-main"><b>${esc(q.name)}</b><small>${q.deadline?"الموعد: "+esc(dateText(q.deadline)):"بدون موعد نهائي"} · +${q.xpReward} XP</small></div><button class="small-btn complete" data-action="complete-quest" data-id="${q.id}" type="button">إكمال</button></div>`).join(""):'<div class="empty">لا توجد مهمات نشطة. أضف مهمة جديدة وابدأ أول خطوة.</div>';
 const dashboardAlerts=$("dashboardAlerts");
 if(dashboardAlerts){const alerts=[];const pending=pendingPenalties().length;if(pending)alerts.push(`<div class="stack-item"><span class="stat-icon">⚠</span><div class="stack-main"><b>${pending} عقوبة مستحقة</b><small>نفّذها وسجّل التنفيذ قبل تحصيل مكافآت المهام.</small></div><button class="small-btn" data-goto="penalties" type="button">عرض</button></div>`);const overdue=state.quests.filter(q=>q.status==="active"&&q.deadline&&new Date(q.deadline).getTime()<Date.now()).length;if(overdue)alerts.push(`<div class="stack-item"><span class="stat-icon">⌛</span><div class="stack-main"><b>${overdue} مهمة تجاوزت موعدها</b><small>راجعها وسجّل الفشل أو حدّث خطتك.</small></div><button class="small-btn" data-goto="quests" type="button">مراجعة</button></div>`);if(state.focusSession)alerts.push(`<div class="stack-item"><span class="stat-icon">◷</span><div class="stack-main"><b>جلسة تركيز ${state.focusSession.status==="paused"?"متوقفة":"نشطة"}</b><small>ارجع للمهمة المرتبطة بالجلسة.</small></div><button class="small-btn" data-goto="quests" type="button">عرض</button></div>`);if(!alerts.length)alerts.push('<div class="empty">النظام مستقر — لا توجد تنبيهات عاجلة الآن.</div>');dashboardAlerts.innerHTML=alerts.join("");}
}
function render(){updateLevel();const r=rank(),done=state.quests.filter(q=>q.status==="done").length,active=state.quests.filter(q=>q.status==="active").length,pen=pendingPenalties().length,level=levelProgress();$("rankBadge").textContent="RANK "+r.name;$("coinBalance").textContent=state.coins;$("shopCoins").textContent=state.coins;$("heroCoins").textContent=state.coins;$("playerNameSide").textContent=state.profile.name||"HUNTER";renderAvatar();$("playerLevelSide").textContent="LEVEL "+state.level;$("todayLabel").textContent=new Date().toLocaleDateString("ar-EG",{weekday:"short",month:"short",day:"numeric"});$("heroRank").textContent=r.title;$("heroQuote").textContent=state.profile.goal?("MAIN QUEST: "+state.profile.goal):"ابدأ صغيرًا. التزم. تطوّر.";$("levelText").textContent="LEVEL "+state.level;$("xpText").textContent=`${level.earned.toLocaleString()} / ${level.needed.toLocaleString()} XP`;$("xpBar").style.width=level.percent+"%";$("completedTotal").textContent=done;$("penaltyCount").textContent=pen;$("shopLockLabel").textContent=shopUnlocked()?"✓":"A";renderStats();renderDashboard();renderQuests();renderDungeons();renderShadows();renderShop();renderAnalytics();renderPenalties();renderEvolution();renderSettings();renderGrowth();renderAchievements();$("profileForm")&&($("playerName").value=state.profile.name||"");syncPenaltyNotice();}
function derivedStats(){const done=state.quests.filter(q=>q.status==="done"),failed=state.quests.filter(q=>q.status==="failed"),focus=(state.focusLogs||[]).reduce((n,x)=>n+(x.minutes||0),0);const rate=(done.length+failed.length)?done.length/(done.length+failed.length):0;const out={};for(const st of STATS){const count=done.filter(q=>q.stat===st.key).length;const mins=done.filter(q=>q.stat===st.key).reduce((n,q)=>n+(q.focusSeconds||0)/60,0);out[st.key]=Math.min(100,Math.max(1,Math.round(1+count*2+Math.sqrt(mins)*0.8+(st.key==="discipline"?state.streak*1.5+rate*10:0))));}out.vitality=Math.min(100,Math.max(1,Math.round(out.vitality+Math.min(10,focus/120))));const unlocked=(state.shadows||[]).map(id=>shadowPerk({id}));for(const sh of (state.dungeonSystem.shadows||[]))unlocked.push({stat:"discipline",amount:1});for(const perk of unlocked)out[perk.stat]=Math.min(100,out[perk.stat]+perk.amount);return out;}
function renderStats(){const ds=derivedStats();$("statusStats").innerHTML=STATS.map(s=>`<div class="stat-card"><div class="stat-top"><span>${s.name}</span><span class="stat-icon">${s.icon}</span></div><div class="stat-number">${ds[s.key]}<small> / 100</small></div><div class="mini-progress"><i style="width:${ds[s.key]}%"></i></div></div>`).join("");}
function questHTML(q){const status=q.status==="done"?'<span class="tag green">مكتملة</span>':q.status==="failed"?'<span class="tag red">فشلت</span>':'<span class="tag">نشطة</span>';const deadline=q.deadline?`<span class="tag ${new Date(q.deadline).getTime()<Date.now()&&q.status==="active"?"red":""}">⌛ ${esc(dateText(q.deadline))}</span>`:"";const focusTag=q.focusMinutes?`<span class="tag gold">تركيز ${q.focusMinutes} د · سجل ${Math.floor((q.focusSeconds||0)/60)} د</span>`:"";const session=state.focusSession&&state.focusSession.questId===q.id?`<div class="focus-running" id="focusGlobalStatus">${state.focusSession.status==="paused"?"جلسة التركيز متوقفة مؤقتًا":"جلسة التركيز نشطة"}</div><button class="small-btn" data-action="toggle-focus">${state.focusSession.status==="paused"?"استئناف":"إيقاف مؤقت"}</button><button class="small-btn delete" data-action="cancel-focus">إلغاء الجلسة</button>`:"";const strictLocked=state.settings.strictMode&&Date.now()-new Date(q.createdAt).getTime()>600000;return `<article class="quest-card"><div class="quest-mark">${q.type==="main"?"✦":q.type==="emergency"?"⚠":"◈"}</div><div class="quest-body"><h3>${esc(q.name)}</h3><p>${esc(q.description||"لا يوجد وصف")} ${q.dcShielded?" · 🛡 درع نشط":""} ${q.boostXP?" · ⚔ XP+":""} ${q.boostDC?" · ♢ DC+":""}</p><div class="tags"><span class="tag">${esc(TYPES[q.type]||q.type)}</span><span class="tag">${esc(DIFFICULTIES[q.difficulty]||q.difficulty)}</span><span class="tag">+${q.xpReward} XP</span><span class="tag gold">+${q.dcReward} DC</span>${status}${deadline}${focusTag}</div>${session}</div><div class="quest-actions">${q.status==="active"?`${q.focusMinutes?`<button class="small-btn" data-action="start-focus" data-id="${q.id}" ${state.focusSession?"disabled":""}>▶ بدء التركيز</button>`:""}<button class="small-btn complete" data-action="complete-quest" data-id="${q.id}">✓ إكمال</button><button class="small-btn" data-action="edit-quest" data-id="${q.id}" ${strictLocked?'disabled title="Strict Mode"':''}>تعديل</button><button class="small-btn delete" data-action="fail-quest" data-id="${q.id}">فشل</button>`:`<button class="small-btn delete" data-action="delete-quest" data-id="${q.id}" ${strictLocked?'disabled title="Strict Mode"':''}>حذف</button>`}</div></article>`;}
function renderQuests(){let list=state.quests.slice();if(currentFilter!=="all"){if(["daily","weekly","main","emergency"].includes(currentFilter))list=list.filter(q=>q.type===currentFilter);else if(currentFilter==="active"||currentFilter==="done")list=list.filter(q=>q.status===currentFilter);}list.sort((a,b)=>{if(a.status==="active"&&b.status!=="active")return -1;if(b.status==="active"&&a.status!=="active")return 1;return new Date(b.createdAt)-new Date(a.createdAt);});$("questList").innerHTML=list.length?list.map(questHTML).join(""):'<div class="empty">لا توجد مهام في هذا القسم. أضف مهمة جديدة للبدء.</div>';}
function renderDungeons(){const ds=state.dungeonSystem,done=state.quests.filter(q=>q.status==="done").length,next=nextDungeonMilestone(),within=done%10,pct=within*10;let html=`<article class="feature-card dungeon-progress-card"><div class="card-icon">◈</div><span class="tag">SYSTEM TRIGGER</span><h3>الزنزانة التالية</h3><p>كل 10 مهام مكتملة تفتح زنزانة جديدة. رتبة الزعيم ومستوى التحدي يتغيران حسب رتبتك وقت الدخول.</p><div class="progress"><i style="width:${pct}%"></i></div><div class="card-bottom"><span class="card-state">${within} / 10 مهمات نحو البوابة</span><span class="price">RANK ${rank().name}</span></div>${ds.pendingMilestones.length&&!ds.current?'<div class="card-bottom"><button class="primary-btn" data-action="open-dungeon-prompt">دخول الزنزانة المفتوحة</button></div>':''}</article>`;const d=ds.current;if(d){const checked=d.steps.filter(x=>x.done).length;html+=`<article class="feature-card dungeon-active"><div class="card-icon">☠</div><span class="tag ${d.status==="active"?"red":"green"}">ACTIVE DUNGEON · RANK ${esc(d.rank)}</span><h3>الزعيم: ${esc(d.boss)}</h3><p>الزنزانة رقم ${d.milestone}. هدفك ليس أن تصبح مثاليًا؛ هدفك أن تكسر حلقة العادة بخطوات قابلة للتنفيذ خلال ${d.durationDays} أيام.</p><div class="tags"><span class="tag">بدأت: ${esc(dateText(d.startedAt))}</span><span class="tag">الموعد: ${esc(dateText(d.deadlineAt))}</span><span class="tag gold">+${d.rewardXP} XP</span><span class="tag gold">+${d.rewardDC} DC</span></div><div class="dungeon-steps">${d.steps.map((st,i)=>`<label class="dungeon-step ${st.done?"is-done":""}"><input type="checkbox" data-dungeon-step="${st.id}" ${st.done?"checked":""}><span><b>المهمة ${i+1}</b><small>${esc(st.text)}</small></span></label>`).join("")}</div><div class="progress"><i style="width:${checked/d.steps.length*100}%"></i></div><div class="card-bottom"><span class="card-state">${checked} / ${d.steps.length} أهداف مكتملة</span><button class="primary-btn" data-action="defeat-dungeon" ${checked<d.steps.length?"disabled":""}>هزيمة الزعيم</button></div></article>`;}if(ds.pendingMilestones.length&&!ds.current){html+=`<div class="empty">بوابة رتبة ${esc(rank().name)} جاهزة. افتحها واختر العادة السيئة التي ستواجهها.</div>`;}if(!d&&!ds.pendingMilestones.length){html+=`<div class="empty">لا توجد زنزانة نشطة الآن. أكمل ${10-within} مهمة أخرى لفتح الزنزانة التالية.</div>`;}if(ds.history.length){html+=`<div class="dungeon-history-wrap"><div class="section-head"><div><p class="eyebrow">DUNGEON RECORD</p><h2>سجل الزنزانات</h2></div></div><div class="card-grid">${ds.history.map(h=>`<article class="feature-card"><div class="card-icon">${h.status==="defeated"?"♟":"⌛"}</div><span class="tag ${h.status==="defeated"?"green":"red"}">${h.status==="defeated"?"BOSS DEFEATED":"TIME EXPIRED"} · RANK ${esc(h.rank)}</span><h3>${esc(h.boss)}</h3><p>${h.status==="defeated"?"واجهت العادة وأكملت تحديها. يمكنك استدعاء هذا الظل إلى جيشك.":"انتهى وقت التحدي؛ الفشل هنا بيانات للتعديل، ويمكنك إعادة المحاولة."}</p><div class="card-bottom"><span class="card-state">بوابة المهمة ${h.milestone}</span>${h.status==="defeated"?(h.arisen?'<span class="tag green">ARISEN ✓</span>':`<button class="primary-btn" data-action="arise-boss" data-id="${h.id}">ARISE ♟</button>`):`<button class="ghost-btn" data-action="retry-dungeon" data-id="${h.id}">إعادة المحاولة</button>`}</div></article>`).join("")}</div></div>`;}$("dungeonGrid").innerHTML=html;}
function shadowLimit(){const i=rankIndex();return i>=RANKS.length-1?Infinity:[5,8,12,18,25,40][i];}
function shadowPerk(sh){const map={first:{stat:"discipline",amount:1,label:"+1 انضباط"},disciplined:{stat:"vitality",amount:2,label:"+2 حيوية"},veteran:{stat:"strength",amount:2,label:"+2 قوة"},elite:{stat:"intelligence",amount:3,label:"+3 ذكاء"},monarch:{stat:"agility",amount:5,label:"+5 رشاقة"}};return map[sh.id]||{stat:"discipline",amount:1,label:"+1 انضباط"};}
function renderShadows(){const ds=state.dungeonSystem.shadows||[],all=state.shadows.map(id=>SHADOWS.find(x=>x.id===id)).filter(Boolean).map(sh=>({...sh,source:"milestone"})).concat(ds.map(sh=>({...sh,source:"boss"})));const limit=shadowLimit();$("shadowCount").textContent=`${all.length} / ${limit===Infinity?"∞":limit} Shadows`;const cap=$("shadowCapacity");if(cap)cap.innerHTML=`<div class="panel-head"><h3>سعة جيش الظلال</h3><span class="soft-pill">الرتبة ${rank().name}</span></div><p>المستخدم: <b>${all.length}</b> من <b>${limit===Infinity?"غير محدود":limit}</b>. ${limit===Infinity?"رتبة S+: السعة غير محدودة.":"ترقية الرتبة تزيد سعة الجيش."}</p>`;const standard=SHADOWS.map(sh=>{const unlocked=state.shadows.includes(sh.id),perk=shadowPerk(sh);return `<article class="feature-card"><div class="card-icon">${unlocked?"♟":"▧"}</div><span class="tag ${unlocked?"green":""}">${unlocked?"UNLOCKED":"LOCKED"}</span><h3>${unlocked?sh.name:"??????"}</h3><p>${unlocked?sh.desc:`يتطلب إكمال ${sh.at} مهمة.`}</p><div class="card-bottom"><span class="card-state">${sh.ar}</span><span class="price">${perk.label}</span></div></article>`;}).join("");const bosses=ds.map(sh=>{const perk=shadowPerk({id:"boss"});return `<article class="feature-card shadow-boss-card"><div class="card-icon">♟</div><span class="tag green">ARISE · RANK ${esc(sh.rank)}</span><h3>${esc(sh.name)}</h3><p>${esc(sh.desc)}</p><div class="card-bottom"><span class="card-state">Boss Shadow · +1 انضباط</span><span class="price">BOUND</span></div></article>`}).join("");$("shadowGrid").innerHTML=bosses+standard;}
function renderShop(){$("shopLocked").classList.toggle("hidden",shopUnlocked());$("shopGrid").classList.toggle("hidden",!shopUnlocked());$("inventoryPanel").classList.toggle("hidden",!shopUnlocked());$("shopGrid").innerHTML=SHOP.map(i=>{const owned=activeItem(i.id)?.qty||0;return `<article class="feature-card"><div class="card-icon">${i.icon}</div><span class="tag">${i.kind==="consumable"?"CONSUMABLE":"EQUIPMENT"}</span><h3>${i.name}</h3><p><b>${i.ar}</b><br>${i.desc}</p><div class="card-bottom"><span class="price">◈ ${i.price} DC</span><button class="primary-btn" data-action="buy-item" data-id="${i.id}" ${state.coins<i.price?"disabled":""}>شراء</button></div><div class="card-bottom"><span class="card-state">في المخزون: ${owned}</span>${owned?`<button class="ghost-btn" data-action="use-item" data-id="${i.id}">استخدام</button>`:""}</div></article>`;}).join("");const inventory=state.inventory.filter(i=>i.qty>0);$("inventoryList").innerHTML=inventory.length?inventory.map(i=>{const item=SHOP.find(s=>s.id===i.id);return `<div class="inventory-item">${item?.icon||"◈"} ${esc(item?.ar||i.id)} × ${i.qty}<small>${item?.name||""}</small></div>`;}).join(""):'<span class="muted">المخزون فارغ. بعد الوصول إلى رتبة A، يمكنك شراء العناصر من المتجر.</span>';}
function renderAnalytics(){const done=state.quests.filter(q=>q.status==="done").length,failed=state.quests.filter(q=>q.status==="failed").length,total=done+failed,rate=total?Math.round(done/total*100):0;const deadlines=state.quests.filter(q=>q.deadline&&["done","failed"].includes(q.status));const onTime=deadlines.filter(q=>q.status==="done"&&q.completedAt&&new Date(q.completedAt)<=new Date(q.deadline)).length;const deadlineRate=deadlines.length?Math.round(onTime/deadlines.length*100):0;const focusMins=Math.floor((state.focusLogs||[]).reduce((n,x)=>n+(x.minutes||0),0));$("metricGrid").innerHTML=[["إجمالي XP",state.xp],["مهام مكتملة",done],["نسبة النجاح",rate+"%"],["سلسلة الالتزام",state.streak+" يوم"],["الالتزام بالمواعيد",deadlineRate+"%"],["وقت التركيز",focusMins+" دقيقة"]].map(m=>`<div class="metric-card"><span>${m[0]}</span><b>${m[1]}</b></div>`).join("");$("analyticsStats").innerHTML=STATS.map(s=>`<div class="stack-item"><div class="stack-main"><b>${s.name}</b><small>المستوى ${derivedStats()[s.key]}</small><div class="mini-progress"><i style="width:${derivedStats()[s.key]}%"></i></div></div></div>`).join("");const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-i);const start=d.getTime(),end=start+86400000;const completed=state.quests.filter(q=>q.status==="done"&&q.completedAt&&new Date(q.completedAt).getTime()>=start&&new Date(q.completedAt).getTime()<end).length;const failedToday=state.quests.filter(q=>q.status==="failed"&&((q.failedAt&&new Date(q.failedAt).getTime()>=start&&new Date(q.failedAt).getTime()<end)||(!q.failedAt&&q.deadline&&new Date(q.deadline).getTime()>=start&&new Date(q.deadline).getTime()<end))).length;days.push({label:d.toLocaleDateString("ar-EG",{weekday:"short"}),date:d.toLocaleDateString("ar-EG",{day:"numeric",month:"numeric"}),completed,failed:failedToday});}const max=Math.max(1,...days.map(d=>d.completed+d.failed));$("weeklyChart").innerHTML=days.map(d=>`<div class="week-day"><div class="week-bars"><i class="week-done" style="height:${Math.max(d.completed?5:0,d.completed/max*100)}%" title="${d.completed} إنجاز"></i><i class="week-failed" style="height:${Math.max(d.failed?5:0,d.failed/max*100)}%" title="${d.failed} تعثر"></i></div><b>${d.completed}</b><small>${d.label}</small></div>`).join("");const best=days.reduce((a,b)=>b.completed>a.completed?b:a,days[0]),worst=days.reduce((a,b)=>b.failed>a.failed?b:a,days[0]);$("weeklySummary").innerHTML=`<span>🏆 أكثر يوم إنجازًا: <b>${best.label}</b> (${best.completed})</span><span>⚠ أكثر يوم تعثرًا مسجلًا: <b>${worst.label}</b> (${worst.failed})</span><span>نسبة الالتزام بالموعد النهائي: <b>${deadlineRate}%</b></span>`;$("activityLog").innerHTML=state.history.length?state.history.slice(0,8).map(h=>`<div class="stack-item"><span>${h.type==="success"?"✓":h.type==="danger"?"⚠":"◈"}</span><div class="stack-main"><b>${esc(h.text)}</b><small>${esc(dateText(h.at))}</small></div></div>`).join(""):'<div class="empty">سيظهر هنا سجل نشاطك عند بدء استخدام النظام.</div>';}
